mapper.select:
SELECT
  NVL(SUM(NVL(KURIKOSHIKIN, 0)), 0) KURIKOSHIKINGOUKEI
  , NVL(SUM(NVL(KONKAITAXNUKIURIKIN, 0) + NVL(KONKAISHOHITAXKIN, 0)), 0) KONKAISHOHITAXKINGOUKEI
FROM
  S07T001T
WHERE
  APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
  AND SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
  AND SHIMEDYDM = #{skyshimedydm,jdbcType=VARCHAR}
  AND SHIMEDD = #{skyshimedd,jdbcType=VARCHAR}
  AND YUKOKBN = '1'

SELECT
  MAX(SHIMEDYDM || SHIMEDD) AS SHIMEDYDM
FROM
  S07T001T
WHERE
  APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
  AND SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
  AND YUKOKBN = '1'

SELECT
  SUM(SZDT.KESHIKOMIZD) KESHIKOMIZD
FROM
  S07T001T SZDT
WHERE
  SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
  AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
  AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
  AND SZDT.YUKOKBN = '1'

SELECT T_SKYZD.KONKAISHIMEDD AS SHIMEYMD ,T_SKYZD.SKYSHONO ,T_SKYZD.TOKUISAKICD ,M_TKISK.TOKUISAKINMN1 ,NVL(T_SKYZD.KONKAITAXNUKIURIKIN, '0') + NVL(T_SKYZD.KONKAISHOHITAXKIN, '0') AS URIAGE ,NVL(T_SKYZD.KESHIKOMIZD, '0') AS KESHIKOMIZD ,T_NYKRIREKI.NYKNDD ,T_NYKRIREKI.KSHKMDD ,M_SYSTEMNYU.MOJISETTEIATAI AS NYKINKIND ,M_SYSTEMKESHI.MOJISETTEIATAI AS KSKINKIND ,NVL(T_NYKRIREKI.KESHIKOMIKIN, '0') AS KESHIKOMIKIN ,T_NYKRIREKI.NYKNDNPYNO ,T_SKYZD.SKYPRCSJISSIKBN FROM S07T001T T_SKYZD LEFT OUTER JOIN S10T004T T_NYKRIREKI ON T_NYKRIREKI.APKIHONCD = T_SKYZD.APKIHONCD AND T_NYKRIREKI.SHOPCD = T_SKYZD.SHOPCD AND T_NYKRIREKI.SKYSAKICD = T_SKYZD.SKYSAKICD AND T_NYKRIREKI.TOKUISAKICD = T_SKYZD.TOKUISAKICD AND T_NYKRIREKI.SHOKAISKYSHONO = T_SKYZD.SKYSHONO AND T_NYKRIREKI.YUKOKBN = '1' LEFT OUTER JOIN S02M013T M_TKISK ON M_TKISK.APKIHONCD = T_SKYZD.APKIHONCD AND M_TKISK.SHOPCD = T_SKYZD.SHOPCD AND M_TKISK.TOKUISAKICD = T_SKYZD.TOKUISAKICD LEFT OUTER JOIN S02M006T M_SYSTEMNYU ON M_SYSTEMNYU.APKIHONCD = '000' AND M_SYSTEMNYU.SHOPCD = '000' AND M_SYSTEMNYU.SETTEINO = '050' AND M_SYSTEMNYU.RCRDKBN = 'M' AND M_SYSTEMNYU.SETTEICD = T_NYKRIREKI.NYKNKIND LEFT OUTER JOIN S02M006T M_SYSTEMKESHI ON M_SYSTEMKESHI.APKIHONCD = '000' AND M_SYSTEMKESHI.SHOPCD = '000' AND M_SYSTEMKESHI.SETTEINO = '050' AND M_SYSTEMKESHI.RCRDKBN = 'M' AND M_SYSTEMKESHI.SETTEICD = T_NYKRIREKI.KSHKMNYKNKIND WHERE T_SKYZD.APKIHONCD = #{entity.apkihoncd,jdbcType=VARCHAR} AND T_SKYZD.SHOPCD = #{entity.shopcd,jdbcType=VARCHAR} AND T_SKYZD.SKYSAKICD = #{entity.skysakicd,jdbcType=VARCHAR}
T_SKYZD.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
and T_SKYZD.KSIKKNCD = #{item.ksikknCd}
AND T_SKYZD.KESHIKOMIZD <> 0
AND T_SKYZD.KONKAISHIMEDD >= #{entity.skydydmddstrt,jdbcType=VARCHAR}
AND T_SKYZD.KONKAISHIMEDD <= #{entity.skydydmddshry,jdbcType=VARCHAR}
AND T_SKYZD.SHRYTIDYDMDD >= #{entity.nyknytiddstrt,jdbcType=VARCHAR}
AND T_SKYZD.SHRYTIDYDMDD <= #{entity.nyknytiddshry,jdbcType=VARCHAR}
AND T_SKYZD.YUKOKBN = '1'
AND T_NYKRIREKI.NYKNDD >= #{entity.nyknddstrt,jdbcType=VARCHAR}
AND T_NYKRIREKI.NYKNDD <= #{entity.nyknddshry,jdbcType=VARCHAR}
AND T_NYKRIREKI.KSHKMNYKNKIND IN
#{listItem}
ORDER BY SHIMEYMD ,T_SKYZD.TOKUISAKICD ,T_NYKRIREKI.NYKNDD ,T_NYKRIREKI.NYKNDNPYNO ,T_NYKRIREKI.SEQ

SELECT * FROM (SELECT SHIMEDYDM, SHIMEDD, SKYSAKICD, SKYSAKINMN1, SUM(ZNKKURIKOSHIKIN) SUMZNKKURIKOSHIKIN, SUM(KONKAINYKNKIN) SUMKONKAINYKNKIN, SUM(KONKAITAXNUKIURIKIN) SUMKONKAITAXNUKIURIKIN, SUM(KONKAISHOHITAXKIN) SUMKONKAISHOHITAXKIN, SUM(KONKAITAXNUKIURIKIN + KONKAISHOHITAXKIN) ADDSUM, SUM(KURIKOSHIKIN) SUMKURIKOSHIKIN, RENBAN, SKYPRCSJISSIKBN FROM (SELECT SZDT.SHIMEDYDM SHIMEDYDM, SZDT.SHIMEDD SHIMEDD, SZDT.SKYSAKICD SKYSAKICD, SKSM.SKYSAKINMN1 SKYSAKINMN1, SZDT.ZNKKURIKOSHIKIN ZNKKURIKOSHIKIN, SZDT.KONKAINYKNKIN KONKAINYKNKIN, SZDT.KONKAITAXNUKIURIKIN KONKAITAXNUKIURIKIN, SZDT.KONKAISHOHITAXKIN KONKAISHOHITAXKIN, SZDT.KURIKOSHIKIN KURIKOSHIKIN, SZDT.RENBAN RENBAN, SZDT.SKYPRCSJISSIKBN SKYPRCSJISSIKBN FROM S07T001T SZDT LEFT OUTER JOIN S02M017T SKSM ON SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD WHERE SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SZDT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND SZDT.SKYPRCSJISSIKBN = '1'
AND SZDT.SHIMEDYDM <= #{shimedydm,jdbcType=VARCHAR}
AND SZDT.YUKOKBN = '1' ) GROUP BY SKYSAKICD, SHIMEDYDM, SHIMEDD, SKYSAKINMN1, RENBAN, SKYPRCSJISSIKBN ORDER BY SHIMEDYDM DESC, SHIMEDD DESC ) WHERE ROWNUM <= 2

SELECT * FROM ( SELECT * FROM ( SELECT SKYSAKICD SKYSAKICD, SHIMEDYDM SHIMEDYDM, SHIMEDD SHIMEDD, KAISHUHOHOKBN KAISHUHOHOKBN, KAISHUHOHONM KAISHUHOHONM, NVL(SUM(RGRAYURYO),0) RGRAYURYO, NVL(SUM(RGRAMURYO),0) RGRAMURYO, NVL(SUM(SRMYURYO),0) SRMYURYO, NVL(SUM(SRMMURYO),0) SRMMURYO, NVL(SUM(SONOTAYURYO),0) SONOTAYURYO, NVL(SUM(SONOTAMURYO),0) SONOTAMURYO, NVL(SUM(SEIHINMIZUURI),0) SEIHINMIZUURI, NVL(SUM(RTLRKN),0) RTLRKN, NVL(SUM(SONOTAURIKIN),0) SONOTAURIKIN, NVL(SUM(KONKAITAXNUKIURIKIN),0) KONKAITAXNUKIURIKIN, NVL(SUM(KONKAISHOHITAXKIN),0) KONKAISHOHITAXKIN, NVL(SUM(KONKAITAXNUKIURIKIN),0)+NVL(SUM(KONKAISHOHITAXKIN),0) TAXKOMIURIKEIKIN, NVL(SUM(ZNKKURIKOSHIKIN),0) ZNKKURIKOSHIKIN, NVL(SUM(KONKAINYKNKIN),0) KONKAINYKNKIN, NVL(SUM(KURIKOSHIKIN),0) KURIKOSHIKIN, MAX(RENBAN) RENBAN FROM ( SELECT SZDT.SKYSAKICD SKYSAKICD, SZDT.SHIMEDYDM SHIMEDYDM, SZDT.SHIMEDD SHIMEDD, SZDT.RGRAYURYO RGRAYURYO, SZDT.RGRAMURYO RGRAMURYO, SZDT.SRMYURYO SRMYURYO, SZDT.SRMMURYO SRMMURYO, SZDT.SONOTAYURYO SONOTAYURYO, SZDT.SONOTAMURYO SONOTAMURYO, SZDT.SEIHINMIZUURI SEIHINMIZUURI, SZDT.RTLRKN RTLRKN, SZDT.SONOTAURIKIN SONOTAURIKIN, SZDT.KONKAITAXNUKIURIKIN KONKAITAXNUKIURIKIN, SZDT.KONKAISHOHITAXKIN KONKAISHOHITAXKIN, SZDT.ZNKKURIKOSHIKIN ZNKKURIKOSHIKIN, SZDT.KONKAINYKNKIN KONKAINYKNKIN, SZDT.KURIKOSHIKIN KURIKOSHIKIN, SZDT.KAISHUHOHOKBN KAISHUHOHOKBN, CONM.ITEMNM KAISHUHOHONM, SZDT.RENBAN RENBAN FROM S07T001T SZDT LEFT JOIN S01M004T CONM ON SZDT.KAISHUHOHOKBN = CONM.SETTEIATAI AND CONM.CONDITIONID = 'CN160' WHERE SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SZDT.SHIMEDYDM >= #{shimedydm,jdbcType=VARCHAR}
AND SZDT.KAISHUHOHOKBN <> '7' AND SZDT.YUKOKBN = '1' ) GROUP BY SKYSAKICD, SHIMEDYDM, SHIMEDD, KAISHUHOHOKBN, KAISHUHOHONM UNION ALL SELECT SZDT.SKYSAKICD SKYSAKICD, SZDT.SHIMEDYDM SHIMEDYDM, SZDT.SHIMEDD SHIMEDD, SZDT.KAISHUHOHOKBN KAISHUHOHOKBN, CONM.ITEMNM KAISHUHOHONM, NVL(SZDT.RGRAYURYO,0) RGRAYURYO, NVL(SZDT.RGRAMURYO,0) RGRAMURYO, NVL(SZDT.SRMYURYO,0) SRMYURYO, NVL(SZDT.SRMMURYO,0) SRMMURYO, NVL(SZDT.SONOTAYURYO,0) SONOTAYURYO, NVL(SZDT.SONOTAMURYO,0) SONOTAMURYO, NVL(SZDT.SEIHINMIZUURI,0) SEIHINMIZUURI, NVL(SZDT.RTLRKN,0) RTLRKN, NVL(SZDT.SONOTAURIKIN,0) SONOTAURIKIN, NVL(SZDT.KONKAITAXNUKIURIKIN,0) KONKAITAXNUKIURIKIN, NVL(SZDT.KONKAISHOHITAXKIN,0) KONKAISHOHITAXKIN, NVL(SZDT.KONKAITAXNUKIURIKIN,0) + NVL(SZDT.KONKAISHOHITAXKIN,0) TAXKOMIURIKEIKIN, NVL(SZDT.ZNKKURIKOSHIKIN,0) ZNKKURIKOSHIKIN, NVL(SZDT.KONKAINYKNKIN,0) KONKAINYKNKIN, NVL(SZDT.KURIKOSHIKIN,0) KURIKOSHIKIN, SZDT.RENBAN RENBAN FROM S07T001T SZDT LEFT JOIN S01M004T CONM ON SZDT.KAISHUHOHOKBN = CONM.SETTEIATAI AND CONM.CONDITIONID = 'CN160' WHERE SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SZDT.SHIMEDYDM >= #{shimedydm,jdbcType=VARCHAR}
AND SZDT.KAISHUHOHOKBN = '7' AND SZDT.YUKOKBN = '1' ) ORDER BY
SHIMEDYDM, SHIMEDD, RENBAN
SHIMEDYDM DESC, SHIMEDD DESC, RENBAN DESC
) WHERE ROWNUM <= 23
ORDER BY SHIMEDYDM, SHIMEDD, RENBAN

mapper.update:
UPDATE (
  SELECT
    SZDT.SKYSHONO
    , SZDT.TOKUSOKUJOPRNTDD
    , SZDT.TOKUSOKUJONO
    , SZDT.KOSHAAPKIHONCD
    , SZDT.KOSHASHOPCD
    , SZDT.KOSHACD
    , SZDT.KSHNSYSTMYMD
    , SZDT.KSHNSYSTMJIKAN
    , SZDT.KSHNUNYOYMD
    , SZDT.KSHNIPADRSE
    , SZDT.KSHNPGMID
  FROM
    S07T001T SZDT
    INNER JOIN S02M017T SKSM
      ON (
        SZDT.APKIHONCD = SKSM.APKIHONCD
        AND SZDT.SHOPCD = SKSM.SHOPCD
        AND SZDT.SKYSAKICD = SKSM.SKYSAKICD
        AND SKSM.JIGYOSHOCD = #{jigyoshocd, jdbcType=VARCHAR}
        AND SZDT.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR}
        AND SZDT.SHOPCD = #{shopcd, jdbcType=VARCHAR}
        AND SZDT.SKYSAKICD = #{skysakicd, jdbcType=VARCHAR}
        AND SZDT.SHIMEDYDM = #{shimedydm, jdbcType=VARCHAR}
        AND SZDT.SHIMEDD = #{shimedd, jdbcType=VARCHAR}
      )
) SZDT
SET
  TOKUSOKUJOPRNTDD = #{kshnunyoymd, jdbcType=VARCHAR}
  , KOSHAAPKIHONCD = #{koshaapkihoncd, jdbcType=VARCHAR}
  , KOSHASHOPCD = #{koshashopcd, jdbcType=VARCHAR}
  , KOSHACD = #{koshacd, jdbcType=VARCHAR}
  , KSHNSYSTMYMD = #{kshnsystmymd, jdbcType=VARCHAR}
  , KSHNSYSTMJIKAN = #{kshnsystmjikan, jdbcType=VARCHAR}
  , KSHNUNYOYMD = #{kshnunyoymd, jdbcType=VARCHAR}
  , KSHNIPADRSE = #{kshnipadrse, jdbcType=VARCHAR}
  , KSHNPGMID = 'D1503R01'

mapper.select:
SELECT
    MAX( SHIMEDYDM || SHIMEDD ) ASSHIMEDYDM
FROM
    S07T001T
WHERE
    APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
    AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
    AND SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
    AND TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
    AND YUKOKBN = #{yukokbn,jdbcType=VARCHAR}

SELECT /*+ ORDERED */ * FROM ( SELECT DISTINCT SKSM1.APKIHONCD APKIHONCD ,SKSM1.SHOPCD SHOPCD ,SKSM1.SKYSAKICD SKYSAKICD ,SKSM1.SKYSAKINMN1 SKYSAKINMN1 ,SKSM1.JIGYOSHOCD JIGYOSHOCD ,SKSM1.KONKAISHIMEDD KONKAISHIMEDD ,SKSM1.KAISHUHOHOKBN KAISHUHOHOKBN ,SKSM1.KAISHUHOHOKBNNM KAISHUHOHOKBNNM ,SKSM1.TAIRYUKBN TAIRYUKBN ,SKSM1.TAIRYUKBNNM TAIRYUKBNNM ,SKSM1.STATUS STATUS ,SKSM1.YUBINNO YUBINNO FROM ( SELECT SKSM.APKIHONCD APKIHONCD ,SKSM.SHOPCD SHOPCD ,SKSM.SKYSAKICD SKYSAKICD ,SKSM.SKYSAKINMN1 SKYSAKINMN1 ,SKSM.JIGYOSHOCD JIGYOSHOCD ,SZDT1.KAISHUHOHOKBN KAISHUHOHOKBN ,CDT1.ITEMNM KAISHUHOHOKBNNM ,SKSM.TAIRYUKBN TAIRYUKBN ,CDT2.ITEMNM TAIRYUKBNNM
,CASE WHEN SZDT1.SKYSHOPRNTDD = '00000000' THEN '0' ELSE '1' END STATUS
, SKSM.YUBINNO , SZDT1.KURIKOSHIKIN KURIKOSHIKIN , SZDT1.URIAGE URIAGE , SKSM.SKYHOHOKBN SKYHOHOKBN , SKSM.KAIREKIN KAIREKIN , SZDT1.TOKUISAKICD TOKUISAKICD , SZDT1.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , SZDT1.SHIMEDD SHIMEDD , SZDT1.SHIMEDYDM SHIMEDYDM , SZDT1.KONKAISHIMEDD KONKAISHIMEDD FROM S02M017T SKSM INNER JOIN ( SELECT APKIHONCD ,SHOPCD ,SKYSAKICD ,SHIMEDYDM ,SHIMEDD ,KONKAISHIMEDD ,SKYPRCSJISSIKBN ,TOKUISAKICD ,KAISHUHOHOKBN ,SKYSHOPRNTDD ,KONKAITAXNUKIURIKIN + KONKAISHOHITAXKIN URIAGE ,KURIKOSHIKIN FROM S07T001T SZDT WHERE
SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SZDT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR}
AND SZDT.SHIMEDD = #{extractshimedd,jdbcType=VARCHAR}
AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SZDT.SKYPRCSJISSIKBN = '1'
AND SZDT.YUKOKBN = '1'
SZDT.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
AND SZDT.KSIKKNCD = #{item.ksikknCd}
) SZDT1 ON( SKSM.APKIHONCD = SZDT1.APKIHONCD AND SKSM.SHOPCD = SZDT1.SHOPCD AND SKSM.SKYSAKICD = SZDT1.SKYSAKICD )
LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD, TKSM.SHOPCD SHOPCD, TKSM.SKYSAKICD SKYSAKICD, MIN(TOKUISAKIJOTAI) TOKUISAKIJOTAI, MIN(JOTAISTS) JOTAISTS FROM S02M013T TKSM GROUP BY TKSM.APKIHONCD, TKSM.SHOPCD, TKSM.SKYSAKICD ) TKSM1 ON( TKSM1.APKIHONCD = SKSM.APKIHONCD AND TKSM1.SHOPCD = SKSM.SHOPCD AND TKSM1.SKYSAKICD = SKSM.SKYSAKICD )
LEFT JOIN S01M004T CDT1 ON CDT1.CONDITIONID = 'CN160' AND CDT1.SETTEIATAI = SZDT1.KAISHUHOHOKBN
LEFT JOIN S01M004T CDT2 ON CDT2.CONDITIONID = 'CN085' AND CDT2.ITEMNO = SKSM.TAIRYUKBN WHERE
SKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND SKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND SKSM.EIGYOTNSHACD = #{eigyotnshacd,jdbcType=VARCHAR}
AND SKSM.KAISHUTNSHACD = #{kaishutnshacd,jdbcType=VARCHAR}
AND SZDT1.SKYSHOPRNTDD = '00000000'
AND SZDT1.SKYSHOPRNTDD <> '00000000'
AND SKSM.YUKOKBN = '1'
AND SKSM.SKYSAKIKANRIKBN = #{skysakikanrikbn,jdbcType=VARCHAR}
AND SKSM.SHUKINDD = #{shukindd,jdbcType=VARCHAR}
AND SKSM.SKYSAKINMKANA LIKE '%' || #{skysakinmkana,jdbcType=VARCHAR} || '%'
AND TKSM1.SKYSAKICD IS NOT NULL
AND TKSM1.SKYSAKICD IS NULL
AND SKSM.SKYKBN = '2'
AND SKSM.SKYKBN = '1'
AND SKSM.HAYADASIFLG = '1'
AND SKSM.SKYMEISAISOFUKBN = '1'
AND SKSM.SKYMEISAISOFUKBN = '0'
AND SKSM.SKYSHOHASSOUITAKUUMU = '1'
AND SKSM.SKYSHOHASSOUITAKUUMU = '0'
SKSM.ACIKEIYUFLG = #{item.value}
) SKSM1
LEFT JOIN ( SELECT * FROM ( SELECT URI.APKIHONCD APKIHONCD , URI.SHOPCD SHOPCD , URI.SKYSAKICD SKYSAKICD , URI.SKYSHIMEDYDM SKYSHIMEDYDM , URI.SKYSHIMEDD SKYSHIMEDD , URI.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , URI.TOKUISAKICD TOKUISAKICD , ROW_NUMBER() OVER(PARTITION BY URI.APKIHONCD , URI.SHOPCD , URI.SKYSHIMEDYDM , URI.SKYSHIMEDD , URI.SKYPRCSJISSIKBN , URI.TOKUISAKICD ORDER BY URI.TOKUISAKICD ) SEQ FROM S06T001T URI WHERE URI.YUKOKBN = '1'
AND URI.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND URI.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND URI.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR}
AND URI.SKYSHIMEDD = #{extractshimedd,jdbcType=VARCHAR}
AND URI.SKYPRCSJISSIKBN = '1'
AND URI.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
) URIT2 WHERE URIT2.SEQ = 1 ) URIT
ON ( SKSM1.APKIHONCD = URIT.APKIHONCD AND SKSM1.SHOPCD = URIT.SHOPCD AND SKSM1.SKYSAKICD = URIT.SKYSAKICD AND SKSM1.SHIMEDYDM = URIT.SKYSHIMEDYDM AND SKSM1.SHIMEDD = URIT.SKYSHIMEDD AND SKSM1.SKYPRCSJISSIKBN = URIT.SKYPRCSJISSIKBN AND SKSM1.TOKUISAKICD = URIT.TOKUISAKICD )
LEFT JOIN ( SELECT * FROM ( SELECT NYU.APKIHONCD APKIHONCD , NYU.SHOPCD SHOPCD , NYU.SKYSAKICD SKYSAKICD , NYU.SKYSHIMEDYDM SKYSHIMEDYDM , NYU.SKYSHIMEDD SKYSHIMEDD , NYU.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , NYU.TOKUISAKICD TOKUISAKICD , ROW_NUMBER() OVER(PARTITION BY NYU.APKIHONCD , NYU.SHOPCD , NYU.SKYSHIMEDYDM , NYU.SKYSHIMEDD , NYU.SKYPRCSJISSIKBN , NYU.TOKUISAKICD ORDER BY NYU.TOKUISAKICD ) SEQ FROM S10T001T NYU WHERE NYU.YUKOKBN = '1'
AND NYU.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
AND NYU.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND NYU.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR}
AND NYU.SKYSHIMEDD = #{extractshimedd,jdbcType=VARCHAR}
AND NYU.SKYPRCSJISSIKBN = '1'
AND NYU.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
) NYUT2 WHERE NYUT2.SEQ = 1 ) NYUT
ON ( SKSM1.APKIHONCD = NYUT.APKIHONCD AND SKSM1.SHOPCD = NYUT.SHOPCD AND SKSM1.SKYSAKICD = NYUT.SKYSAKICD AND SKSM1.SHIMEDYDM = NYUT.SKYSHIMEDYDM AND SKSM1.SHIMEDD = NYUT.SKYSHIMEDD AND SKSM1.SKYPRCSJISSIKBN = NYUT.SKYPRCSJISSIKBN AND SKSM1.TOKUISAKICD = NYUT.TOKUISAKICD )
WHERE ( ( ( SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE > '0' ) OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN > '0' ) )
OR ( ( ( SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0' ) OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) )
AND ( URIT.SKYSAKICD IS NOT NULL OR NYUT.SKYSAKICD IS NOT NULL ) )
OR ( ( ( SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0' ) OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) ) AND URIT.SKYSAKICD IS NULL AND NYUT.SKYSAKICD IS NULL )
OR ( ( ( SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0' ) OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) ) AND SKSM1.KAIREKIN <> '0' )
) ORDER BY
SKSM1.SKYSAKICD
SKSM1.YUBINNO, SKSM1.SKYSAKICD
) WHERE ROWNUM <= #{meisaimaxline} + 1

SELECT * FROM ( SELECT DISTINCT SKSM1.APKIHONCD APKIHONCD , SKSM1.SHOPCD SHOPCD , SKSM1.SKYSAKICD SKYSAKICD , SKSM1.SKYSAKINMN1 SKYSAKINMN1 , SKSM1.JIGYOSHOCD JIGYOSHOCD , SKSM1.KONKAISHIMEDD KONKAISHIMEDD , SKSM1.KAISHUHOHOKBN KAISHUHOHOKBN , SKSM1.KAISHUHOHOKBNNM KAISHUHOHOKBNNM , SKSM1.TAIRYUKBN TAIRYUKBN , SKSM1.TAIRYUKBNNM TAIRYUKBNNM , SKSM1.STATUS STATUS , SKSM1.YUBINNO YUBINNO FROM ( SELECT SKSM.APKIHONCD APKIHONCD , SKSM.SHOPCD SHOPCD , SKSM.SKYSAKICD SKYSAKICD , SKSM.SKYSAKINMN1 SKYSAKINMN1 , SKSM.JIGYOSHOCD JIGYOSHOCD , SZDT1.KAISHUHOHOKBN KAISHUHOHOKBN , SKSM.TAIRYUKBN TAIRYUKBN , CASE WHEN SZDT1.RIYOMEISAISHOPRNTDD = '00000000' THEN '0' ELSE '1' END STATUS , SKSM.YUBINNO , SZDT1.KURIKOSHIKIN KURIKOSHIKIN , SZDT1.URIAGE URIAGE , SKSM.SKYHOHOKBN SKYHOHOKBN , SKSM.KAIREKIN KAIREKIN , SZDT1.TOKUISAKICD TOKUISAKICD , SZDT1.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , SZDT1.SHIMEDD SHIMEDD , SZDT1.SHIMEDYDM SHIMEDYDM , CDT2.ITEMNM TAIRYUKBNNM , CDT1.ITEMNM KAISHUHOHOKBNNM , SZDT1.KONKAISHIMEDD KONKAISHIMEDD FROM S02M017T SKSM INNER JOIN ( SELECT APKIHONCD , SHOPCD , SKYSAKICD , SHIMEDYDM , SHIMEDD , SKYPRCSJISSIKBN , TOKUISAKICD , RIYOMEISAISHOPRNTDD , KONKAITAXNUKIURIKIN + KONKAISHOHITAXKIN URIAGE , KURIKOSHIKIN , KAISHUHOHOKBN , KONKAISHIMEDD FROM S07T001T SZDT WHERE SZDT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND SZDT.SHIMEDD = #{extractshimedd,jdbcType=VARCHAR}
AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SZDT.SKYPRCSJISSIKBN = '1' AND SZDT.YUKOKBN = '1' AND SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
SZDT.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
AND SZDT.KSIKKNCD = #{item.ksikknCd}
) SZDT1 ON ( SKSM.APKIHONCD = SZDT1.APKIHONCD AND SKSM.SHOPCD = SZDT1.SHOPCD AND SKSM.SKYSAKICD = SZDT1.SKYSAKICD ) LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD , TKSM.SHOPCD SHOPCD , TKSM.SKYSAKICD SKYSAKICD , MIN(TOKUISAKIJOTAI) TOKUISAKIJOTAI , MIN(JOTAISTS) JOTAISTS FROM S02M013T TKSM GROUP BY TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.SKYSAKICD ) TKSM1 ON ( TKSM1.APKIHONCD = SKSM.APKIHONCD AND TKSM1.SHOPCD = SKSM.SHOPCD AND TKSM1.SKYSAKICD = SKSM.SKYSAKICD ) LEFT JOIN S01M004T CDT1 ON CDT1.CONDITIONID = 'CN160' AND CDT1.SETTEIATAI = SZDT1.KAISHUHOHOKBN LEFT JOIN S01M004T CDT2 ON CDT2.CONDITIONID = 'CN085' AND CDT2.ITEMNO = SKSM.TAIRYUKBN WHERE SKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
AND SKSM.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{jigyoshocd,jdbcType=VARCHAR}
AND SKSM.EIGYOTNSHACD = #{eigyotnshacd,jdbcType=VARCHAR}
AND SKSM.KAISHUTNSHACD = #{kaishutnshacd,jdbcType=VARCHAR}
AND SZDT1.RIYOMEISAISHOPRNTDD = '00000000'
AND SZDT1.RIYOMEISAISHOPRNTDD <> '00000000'
AND SKSM.YUKOKBN = '1'
AND SKSM.SKYSAKIKANRIKBN = #{skysakikanrikbn,jdbcType=VARCHAR}
AND SKSM.SHUKINDD = #{shukindd,jdbcType=VARCHAR}
AND SKSM.SKYSAKINMKANA LIKE '%' || #{skysakinmkana,jdbcType=VARCHAR} || '%'
AND TKSM1.SKYSAKICD IS NOT NULL
AND TKSM1.SKYSAKICD IS NULL
