AND SKSM.SKYMEISAISOFUKBN = '0'
SKSM.ACIKEIYUFLG = #{item.value}
) SKSM1
LEFT JOIN ( SELECT * FROM ( SELECT URI.APKIHONCD APKIHONCD , URI.SHOPCD SHOPCD , URI.SKYSAKICD SKYSAKICD , URI.SKYSHIMEDYDM SKYSHIMEDYDM , URI.SKYSHIMEDD SKYSHIMEDD , URI.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , URI.TOKUISAKICD TOKUISAKICD , ROW_NUMBER() OVER ( PARTITION BY URI.APKIHONCD , URI.SHOPCD , URI.SKYSHIMEDYDM , URI.SKYSHIMEDD , URI.SKYPRCSJISSIKBN , URI.TOKUISAKICD ORDER BY URI.TOKUISAKICD ) SEQ FROM S06T001T URI WHERE URI.YUKOKBN = '1' AND URI.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND URI.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND URI.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND URI.SKYSHIMEDD = #{extractshimedd,jdbcType=VARCHAR} AND URI.SKYPRCSJISSIKBN = '1'
AND URI.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
) URIT2 WHERE URIT2.SEQ = 1 ) URIT ON ( SKSM1.APKIHONCD = URIT.APKIHONCD AND SKSM1.SHOPCD = URIT.SHOPCD AND SKSM1.SKYSAKICD = URIT.SKYSAKICD AND SKSM1.SHIMEDYDM = URIT.SKYSHIMEDYDM AND SKSM1.SHIMEDD = URIT.SKYSHIMEDD AND SKSM1.SKYPRCSJISSIKBN = URIT.SKYPRCSJISSIKBN AND SKSM1.TOKUISAKICD = URIT.TOKUISAKICD ) LEFT JOIN ( SELECT * FROM ( SELECT NYU.APKIHONCD APKIHONCD , NYU.SHOPCD SHOPCD , NYU.SKYSAKICD SKYSAKICD , NYU.SKYSHIMEDYDM SKYSHIMEDYDM , NYU.SKYSHIMEDD SKYSHIMEDD , NYU.SKYPRCSJISSIKBN SKYPRCSJISSIKBN , NYU.TOKUISAKICD TOKUISAKICD , ROW_NUMBER() OVER ( PARTITION BY NYU.APKIHONCD , NYU.SHOPCD , NYU.SKYSHIMEDYDM , NYU.SKYSHIMEDD , NYU.SKYPRCSJISSIKBN , NYU.TOKUISAKICD ORDER BY NYU.TOKUISAKICD ) SEQ FROM S10T001T NYU WHERE NYU.YUKOKBN = '1' AND NYU.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND NYU.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND NYU.SKYSHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND NYU.SKYSHIMEDD = #{extractshimedd,jdbcType=VARCHAR} AND NYU.SKYPRCSJISSIKBN = '1'
AND NYU.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR}
) NYUT2 WHERE NYUT2.SEQ = 1 ) NYUT ON ( SKSM1.APKIHONCD = NYUT.APKIHONCD AND SKSM1.SHOPCD = NYUT.SHOPCD AND SKSM1.SKYSAKICD = NYUT.SKYSAKICD AND SKSM1.SHIMEDYDM = NYUT.SKYSHIMEDYDM AND SKSM1.SHIMEDD = NYUT.SKYSHIMEDD AND SKSM1.SKYPRCSJISSIKBN = NYUT.SKYPRCSJISSIKBN AND SKSM1.TOKUISAKICD = NYUT.TOKUISAKICD )
WHERE ( ( (SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE > '0') OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN > '0' ) )
OR ( ( (SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0') OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) ) AND ( URIT.SKYSAKICD IS NOT NULL OR NYUT.SKYSAKICD IS NOT NULL ) )
OR ( ( (SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0') OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) ) AND URIT.SKYSAKICD IS NULL AND NYUT.SKYSAKICD IS NULL )
OR ( ( (SKSM1.SKYHOHOKBN = '2' AND SKSM1.URIAGE <= '0') OR ( SKSM1.SKYHOHOKBN = '1' AND SKSM1.KURIKOSHIKIN <= '0' ) ) AND SKSM1.KAIREKIN <> '0' )
) ORDER BY
SKSM1.SKYSAKICD
SKSM1.YUBINNO , SKSM1.SKYSAKICD
) WHERE ROWNUM <= #{meisaimaxline} + 1

