SZDT.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
and SZDT.KSIKKNCD = #{item.ksikknCd}
GROUP BY APKIHONCD , SHOPCD , SKYSAKICD , KAISHUHOHOKBN ) SZDT1 ON ( SKSM.APKIHONCD = SZDT1.APKIHONCD AND SKSM.SHOPCD = SZDT1.SHOPCD AND SKSM.SKYSAKICD = SZDT1.SKYSAKICD ) ) LEFT JOIN ( SELECT TKSM.APKIHONCD APKIHONCD , TKSM.SHOPCD SHOPCD , TKSM.SKYSAKICD SKYSAKICD FROM S02M013T TKSM GROUP BY TKSM.APKIHONCD , TKSM.SHOPCD , TKSM.SKYSAKICD ) TKSM1 ON ( TKSM1.APKIHONCD = SKSM.APKIHONCD AND TKSM1.SHOPCD = SKSM.SHOPCD AND TKSM1.SKYSAKICD = SKSM.SKYSAKICD ) LEFT JOIN S01M004T CDT1 ON CDT1.CONDITIONID = 'CN160' AND CDT1.SETTEIATAI = SZDT1.KAISHUHOHOKBN LEFT JOIN S01M004T CDT2 ON CDT2.CONDITIONID = 'CN085' AND CDT2.ITEMNO = SKSM.TAIRYUKBN WHERE SKSM.APKIHONCD = #{record.apkihoncd,jdbcType=VARCHAR} AND SKSM.SHOPCD = #{record.shopcd,jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{record.jigyoshocd,jdbcType=VARCHAR}
AND SKSM.EIGYOTNSHACD = #{record.eigyotnshacd,jdbcType=VARCHAR}
AND SKSM.KAISHUTNSHACD = #{record.kaishutnshacd,jdbcType=VARCHAR}
