AND M_SKYSK.YUKOKBN = '1' AND T_SKYZD.YUKOKBN = '1'
T_SKYZD.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
and T_SKYZD.KSIKKNCD = #{item.ksikknCd}
AND T_SKYZD.KESHIKOMIZD <> 0
AND T_SKYZD.KONKAISHIMEDD >= #{entity.skydydmddstrt,jdbcType=VARCHAR}
AND T_SKYZD.KONKAISHIMEDD <= #{entity.skydydmddshry,jdbcType=VARCHAR}
AND T_SKYZD.SHRYTIDYDMDD >= #{entity.nyknytiddstrt,jdbcType=VARCHAR}
AND T_SKYZD.SHRYTIDYDMDD <= #{entity.nyknytiddshry,jdbcType=VARCHAR}
AND T_NYKRIREKI.NYKNDD >= #{entity.nyknddstrt,jdbcType=VARCHAR}
AND T_NYKRIREKI.NYKNDD <= #{entity.nyknddshry,jdbcType=VARCHAR}
AND T_NYKRIREKI.KSHKMNYKNKIND IN
#{item}
UNION ALL SELECT T_NYKN.APKIHONCD , T_NYKN.SHOPCD , M_SKYSK.JIGYOSHOCD , T_NYKN.SKYSAKICD , M_SKYSK.SKYSAKINMN1 , M_SKYSK.SKYSAKINMKANA , NULL AS SHIMEYMD , NULL AS SKYSHONO , T_NYKN.TOKUISAKICD AS TKISKCD , M_TKISK.TOKUISAKINMN1 , NULL AS SUMKIN , NULL AS KESHIKOMIZD , T_NYKN.NYKNDD AS NYKNYMD , NULL AS KSHKMDD , M_SYSTEMNYU.MOJISETTEIATAI AS NYKINKIND , NULL AS KSKINKIND , NVL(T_NYKN.NYKNKIN , 0) + NVL(T_NYKN.NEBIKIKIN, 0) + NVL(T_NYKN.TESURYO, 0) AS KESHIKOMIKIN , T_NYKN.DNPYNO AS DENPYONO FROM S02M017T M_SKYSK INNER JOIN S10T001T T_NYKN ON T_NYKN.APKIHONCD = M_SKYSK.APKIHONCD AND T_NYKN.SHOPCD = M_SKYSK.SHOPCD AND T_NYKN.SKYSAKICD = M_SKYSK.SKYSAKICD LEFT OUTER JOIN S02M013T M_TKISK ON M_TKISK.APKIHONCD = T_NYKN.APKIHONCD AND M_TKISK.SHOPCD = T_NYKN.SHOPCD AND M_TKISK.TOKUISAKICD = T_NYKN.TOKUISAKICD LEFT OUTER JOIN S02M006T M_SYSTEMNYU ON M_SYSTEMNYU.APKIHONCD = '000' AND M_SYSTEMNYU.SHOPCD = '000' AND M_SYSTEMNYU.SETTEINO = '050' AND M_SYSTEMNYU.RCRDKBN = 'M' AND M_SYSTEMNYU.SETTEICD = T_NYKN.NYKNKIND WHERE M_SKYSK.APKIHONCD = #{entity.apkihoncd,jdbcType=VARCHAR} AND M_SKYSK.SHOPCD = #{entity.shopcd,jdbcType=VARCHAR}
AND M_SKYSK.SKYSAKICD LIKE #{entity.skysakicd,jdbcType=VARCHAR} || '%'
AND M_SKYSK.YUKOKBN = '1'
AND M_SKYSK.JIGYOSHOCD = #{entity.jigyoshosentaku,jdbcType=VARCHAR}
AND M_SKYSK.GAIBURENKEICD LIKE #{entity.gaiburenkeicd,jdbcType=VARCHAR} || '%'
AND M_SKYSK.SKYSAKINMN1 LIKE '%' || #{entity.skysakinmn,jdbcType=VARCHAR} || '%'
AND M_SKYSK.SKYSAKINMKANA LIKE '%' || #{entity.skysakinmkana,jdbcType=VARCHAR} || '%'
AND M_SKYSK.KINYUKKNKZMEIGIKANA LIKE '%' || #{entity.kzmeigikana,jdbcType=VARCHAR} || '%'
AND M_SKYSK.ZENGINCSTCD LIKE '%' || #{entity.kzfurikaerenkeicd,jdbcType=VARCHAR} || '%'
AND M_SKYSK.TAIRYUKBN IN
#{item}
AND T_NYKN.YUKOKBN = '1'
AND T_NYKN.NYKNDD >= #{entity.nyknddstrt,jdbcType=VARCHAR}
AND T_NYKN.NYKNDD <= #{entity.nyknddshry,jdbcType=VARCHAR}
AND T_NYKN.NYKNKIND IN
#{item}
AND NOT EXISTS ( SELECT 1 FROM S10T004T T_KSKR WHERE T_KSKR.APKIHONCD = T_NYKN.APKIHONCD AND T_KSKR.SHOPCD = T_NYKN.SHOPCD AND T_KSKR.NYKNDNPYNO = T_NYKN.DNPYNO AND T_KSKR.NYKNDNPYNOEDANO = T_NYKN.NYKNDNPYNOEDANO AND T_KSKR.SKYSAKICD = T_NYKN.SKYSAKICD AND T_KSKR.TOKUISAKICD = T_NYKN.TOKUISAKICD )
ORDER BY SHIMEYMD , TKISKCD , NYKNYMD , DENPYONO

