SELECT * FROM (SELECT MAIN.SENTAKU , MAIN.APKIHONCD , MAIN.SHOPCD , MAIN.SKYSAKICD , MAIN.SKYSAKINMN1 , MAIN.JIGYOSHOCD , MAIN.KAISHUHOHOKBN1 , CDT1.ITEMNM AS KAISHUHOHOKBN1NM , MAIN.KAISHUHOHOKBN2 , CDT2.ITEMNM AS KAISHUHOHOKBN2NM , MAIN.TAIRYUKBN , CDT3.ITEMNM AS TAIRYUKBNNM , MAIN.STATUS FROM (
( SELECT /*+ INDEX(SKSM S02M017T_PK) */ (CASE WHEN ( SELECT COUNT(*) FROM S07T001T SZDT WHERE SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD AND SZDT.KONKAISHIMEDD > #{extractshimeymd, jdbcType=VARCHAR}
AND ( SKSM.KAISHUHOHOKBN = '7' OR SZDT.SKYPRCSJISSIKBN = '1' )
AND SZDT.YUKOKBN = '1' ) > 0 OR EXISTS ( SELECT 1 FROM S02M013T TKSM INNER JOIN S06T001T URIT ON ( URIT.APKIHONCD = TKSM.APKIHONCD AND URIT.SHOPCD = TKSM.SHOPCD AND URIT.TOKUISAKICD = TKSM.TOKUISAKICD ) WHERE TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.TOKUISAKICD = SKSM.SKYSAKICD AND URIT.SKYPRCSJISSIDD = 'DAIBIKI' AND URIT.URIDD <= #{extractshimeymd, jdbcType=VARCHAR} AND URIT.YUKOKBN = '1' ) THEN 0 ELSE 1 END) AS SENTAKU , SKSM.APKIHONCD , SKSM.SHOPCD , SKSM.SKYSAKICD , SKSM.SKYSAKINMN1 , SKSM.JIGYOSHOCD , SKSM.TAIRYUKBN , SKSM.KAISHUHOHOKBN AS KAISHUHOHOKBN1 , NULL AS KAISHUHOHOKBN2 , '0' AS STATUS FROM S02M017T SKSM WHERE SKSM.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND SKSM.SHOPCD = #{shopcd, jdbcType=VARCHAR} AND SKSM.YUKOKBN = '1' AND NOT EXISTS ( SELECT 1 FROM S07T001T SZDT WHERE SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD AND SZDT.KONKAISHIMEDD = #{extractshimeymd, jdbcType=VARCHAR} AND SZDT.SKYPRCSJISSIKBN = '1' AND SZDT.YUKOKBN = '1' )
AND SKSM.SKYSAKICD = #{skysakicd, jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{jigyoshocd, jdbcType=VARCHAR}
SKSM.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
AND SKSM.KSIKKNCD = #{item.ksikknCd}
SKSM.ACIKEIYUFLG = #{item.value}
AND SKSM.SKYSHIMEDD >= #{extractshimedd, jdbcType=VARCHAR}
AND SKSM.SKYSHIMEDD = #{extractshimedd, jdbcType=VARCHAR}
AND SKSM.SKYSAKIKANRIKBN = #{skysakikanrikbn, jdbcType=VARCHAR}
AND SKSM.SKYSAKINMKANA LIKE '%'||#{skysakinmkana, jdbcType=VARCHAR}||'%'
AND SKSM.SKYKBN = '2'
AND SKSM.SKYKBN = '1'
AND SKSM.HAYADASIFLG = '1'
AND (
(0 < ( SELECT NVL(SUM(CASE WHEN TKSM.JOTAISTS IN ('02', '06', '10') AND NOT EXISTS ( SELECT /*+ INDEX(NMST S10T001T_IX6) */ 1 FROM S10T001T NMST WHERE NMST.APKIHONCD = TKSM.APKIHONCD AND NMST.SHOPCD = TKSM.SHOPCD AND NMST.SKYSAKICD = TKSM.SKYSAKICD AND NMST.SKYPRCSJISSIDD = '00000000' AND NMST.YUKOKBN = '1' AND NMST.NYKNDD <= #{extractshimeymd, jdbcType=VARCHAR} ) AND NOT EXISTS ( SELECT /*+ INDEX(NMST S10T001T_IX7) */ 1 FROM S10T001T NMST WHERE NMST.APKIHONCD = TKSM.APKIHONCD AND NMST.SHOPCD = TKSM.SHOPCD AND NMST.SKYSAKICD = TKSM.SKYSAKICD AND NMST.SKYSHIMEDYDM = #{shimedydm, jdbcType=VARCHAR} AND NMST.SKYSHIMEDD = #{extractshimedd, jdbcType=VARCHAR} AND NMST.YUKOKBN = '1' ) AND NOT EXISTS ( SELECT /*+ INDEX(URIT S06T001T_IX6) */ 1 FROM S06T001T URIT WHERE URIT.APKIHONCD = TKSM.APKIHONCD AND URIT.SHOPCD = TKSM.SHOPCD AND URIT.TOKUISAKICD = TKSM.TOKUISAKICD AND URIT.SKYPRCSJISSIDD = '00000000' AND URIT.URIDD <= #{extractshimeymd, jdbcType=VARCHAR} AND URIT.YUKOKBN = '1' ) AND NOT EXISTS ( SELECT /*+ INDEX(URIT S06T001T_IX7) */ 1 FROM S06T001T URIT WHERE URIT.APKIHONCD = TKSM.APKIHONCD AND URIT.SHOPCD = TKSM.SHOPCD AND URIT.TOKUISAKICD = TKSM.TOKUISAKICD AND URIT.SKYSHIMEDYDM = #{shimedydm, jdbcType=VARCHAR} AND URIT.SKYSHIMEDD = #{extractshimedd, jdbcType=VARCHAR} AND URIT.YUKOKBN = '1' ) THEN 0 ELSE 1 END), 0) FROM S02M013T TKSM WHERE TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD AND TKSM.YUKOKBN = '1' ) ) OR (EXISTS ( SELECT 1 FROM S07T001T AAA WHERE AAA.APKIHONCD = SKSM.APKIHONCD AND AAA.SHOPCD = SKSM.SHOPCD AND AAA.SKYSAKICD = SKSM.SKYSAKICD AND AAA.KURIKOSHIKIN <> 0 AND AAA.YUKOKBN = '1' AND NOT EXISTS ( SELECT /*+ INDEX(BBB S07T001T_UQ1) */ 1 FROM S07T001T BBB WHERE BBB.APKIHONCD = AAA.APKIHONCD AND BBB.SHOPCD = AAA.SHOPCD AND BBB.SKYSAKICD = AAA.SKYSAKICD AND BBB.TOKUISAKICD = AAA.TOKUISAKICD AND BBB.KONKAISHIMEDD > AAA.KONKAISHIMEDD AND BBB.KONKAISHIMEDD < #{extractshimeymd, jdbcType=VARCHAR} AND BBB.YUKOKBN = '1' ) ) OR)
( NOT EXISTS ( SELECT 1 FROM S02M013T WHERE APKIHONCD = SKSM.APKIHONCD AND SHOPCD = SKSM.SHOPCD AND SKYSAKICD = SKSM.SKYSAKICD ) AND ( EXISTS ( SELECT /*+ INDEX(NMST S10T001T_IX6) */ 1 FROM S10T001T NMST WHERE NMST.APKIHONCD = SKSM.APKIHONCD AND NMST.SHOPCD = SKSM.SHOPCD AND NMST.SKYSAKICD = SKSM.SKYSAKICD AND NMST.SKYPRCSJISSIDD = '00000000' AND NMST.NYKNDD <= #{extractshimeymd, jdbcType=VARCHAR} AND NMST.YUKOKBN = '1' ) OR EXISTS ( SELECT /*+ INDEX(NMST S10T001T_IX7) */ 1 FROM S10T001T NMST WHERE NMST.APKIHONCD = SKSM.APKIHONCD AND NMST.SHOPCD = SKSM.SHOPCD AND NMST.SKYSAKICD = SKSM.SKYSAKICD AND NMST.SKYSHIMEDYDM = #{shimedydm, jdbcType=VARCHAR} AND NMST.SKYSHIMEDD = #{extractshimedd, jdbcType=VARCHAR} AND NMST.NYKNDD <= #{extractshimeymd, jdbcType=VARCHAR} AND NMST.YUKOKBN = '1' ) OR ( EXISTS ( SELECT 1 FROM S07T001T AAA WHERE AAA.APKIHONCD = SKSM.APKIHONCD AND AAA.SHOPCD = SKSM.SHOPCD AND AAA.SKYSAKICD = SKSM.SKYSAKICD AND AAA.KURIKOSHIKIN <> 0 AND AAA.YUKOKBN = '1' AND NOT EXISTS ( SELECT /*+ INDEX(BBB S07T001T_UQ1) */ 1 FROM S07T001T BBB WHERE BBB.APKIHONCD = AAA.APKIHONCD AND BBB.SHOPCD = AAA.SHOPCD AND BBB.SKYSAKICD = AAA.SKYSAKICD AND BBB.TOKUISAKICD = AAA.TOKUISAKICD AND BBB.KONKAISHIMEDD > AAA.KONKAISHIMEDD AND BBB.KONKAISHIMEDD < #{extractshimeymd, jdbcType=VARCHAR} AND BBB.YUKOKBN = '1' ) ) ) ) ) )
) )
UNION ALL
( SELECT (CASE WHEN (SZDT.KESHIKOMIKIN > 0) OR (SZDT.KSISHIMEDYDMDD <> '00000000' AND TO_DATE(SZDT.KSISHIMEDYDMDD, 'YYYYMMDD') < TO_DATE(#{unyoymd, jdbcType=VARCHAR}, 'YYYYMMDD')) OR ( SELECT COUNT(*) FROM S07T001T SZDT WHERE SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD AND SZDT.KONKAISHIMEDD > #{extractshimeymd, jdbcType=VARCHAR} AND SZDT.YUKOKBN = '1' ) > 0 OR (SKSM.KAISHUHOHOKBN <> SZDT.KAISHUHOHOKBN) THEN 0 ELSE 1 END) AS SENTAKU , SKSM.APKIHONCD , SKSM.SHOPCD , SKSM.SKYSAKICD , SKSM.SKYSAKINMN1 , SKSM.JIGYOSHOCD , SKSM.TAIRYUKBN , SKSM.KAISHUHOHOKBN AS KAISHUHOHOKBN1 , SZDT.KAISHUHOHOKBN AS KAISHUHOHOKBN2 , '1' AS STATUS FROM (S02M017T SKSM INNER JOIN ( SELECT SZDT.APKIHONCD , SZDT.SHOPCD , SZDT.SKYSAKICD , SZDT.KAISHUHOHOKBN , SUM( CASE WHEN SZDT.KESHIKOMIKIN <> 0 THEN 1 ELSE 0 END) AS KESHIKOMIKIN , SUM(SZDT.KESHIKOMIZD) AS KESHIKOMIZD , SUM(SZDT.KONKAITAXNUKIURIKIN) AS KONKAITAXNUKIURIKIN , SUM(SZDT.KONKAINYKNKIN) AS KONKAINYKNKIN , SUM(SZDT.KURIKOSHIKIN) AS KURIKOSHIKIN , MAX(SZDT.KSISHIMEDYDMDD) AS KSISHIMEDYDMDD , MIN(SZDT.SKYSHONO) AS SHOKAISKYSHONO FROM S07T001T SZDT WHERE SZDT.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd, jdbcType=VARCHAR} AND SZDT.SHIMEDYDM = #{shimedydm, jdbcType=VARCHAR} AND SZDT.SHIMEDD = #{extractshimedd, jdbcType=VARCHAR} AND SZDT.SKYPRCSJISSIKBN = '1' AND SZDT.YUKOKBN = '1'
SZDT.KAISHUHOHOKBN = #{item.kaishuHohoKbn}
AND SZDT.KSIKKNCD = #{item.ksikknCd}
GROUP BY SZDT.APKIHONCD , SZDT.SHOPCD , SZDT.SKYSAKICD , SZDT.KAISHUHOHOKBN ) SZDT ON ( SKSM.APKIHONCD = SZDT.APKIHONCD AND SKSM.SHOPCD = SZDT.SHOPCD AND SKSM.SKYSAKICD = SZDT.SKYSAKICD ) ) WHERE SKSM.APKIHONCD = #{apkihoncd, jdbcType=VARCHAR} AND SKSM.SHOPCD = #{shopcd, jdbcType=VARCHAR}
AND SKSM.SKYSAKICD = #{skysakicd, jdbcType=VARCHAR}
AND SKSM.JIGYOSHOCD = #{jigyoshocd, jdbcType=VARCHAR}
AND SKSM.SKYSHIMEDD >= #{extractshimedd, jdbcType=VARCHAR}
AND SKSM.SKYSHIMEDD = #{extractshimedd, jdbcType=VARCHAR}
AND SKSM.SKYSAKIKANRIKBN = #{skysakikanrikbn, jdbcType=VARCHAR}
AND SKSM.SKYSAKINMKANA LIKE '%'||#{skysakinmkana, jdbcType=VARCHAR}||'%'
AND SKSM.SKYKBN = '2'
AND SKSM.SKYKBN = '1'
AND SKSM.HAYADASIFLG = '1'
SKSM.ACIKEIYUFLG = #{item.value}
AND EXISTS ( SELECT 1 FROM S02M013T TKSM WHERE TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD )
AND NOT EXISTS ( SELECT 1 FROM S02M013T TKSM WHERE TKSM.APKIHONCD = SKSM.APKIHONCD AND TKSM.SHOPCD = SKSM.SHOPCD AND TKSM.SKYSAKICD = SKSM.SKYSAKICD )
AND ( SELECT COUNT(SKYSAKICD) FROM S10T004T WHERE APKIHONCD = SKSM.APKIHONCD AND SHOPCD = SKSM.SHOPCD AND SKYSAKICD = SKSM.SKYSAKICD AND YUKOKBN = '1' AND KSHKMNYKNKIND = '31' AND SHOKAISKYSHONO = SZDT.SHOKAISKYSHONO AND TRKSDNPYNO IS NULL ) = 0
)
) MAIN LEFT JOIN S01M004T CDT1 ON ( CDT1.CONDITIONID = 'CN160' AND CDT1.SETTEIATAI = MAIN.KAISHUHOHOKBN1 ) LEFT JOIN S01M004T CDT2 ON ( CDT2.CONDITIONID = 'CN160' AND CDT2.SETTEIATAI = MAIN.KAISHUHOHOKBN2 ) LEFT JOIN S01M004T CDT3 ON ( CDT3.CONDITIONID = 'CN085' AND CDT3.ITEMNO = MAIN.TAIRYUKBN ) ORDER BY SKYSAKICD ) WHERE ROWNUM <= #{meisaimaxline} + 1

