SELECT SKYSAKICD SKYSAKICD, SKYKBN SKYKBN, SKYSAKINMN1 SKYSAKINMN1, NVL(SUM(ZNKKURIKOSHIKIN), 0) ZNKKURIKOSHIKIN, NVL(SUM(KONKAINYKNKIN), 0) KONKAINYKNKIN, NVL(SUM(KONKAITAXNUKIURIKIN), 0) KONKAITAXNUKIURIKIN, NVL(SUM(KONKAISHOHITAXKIN), 0) KONKAISHOHITAXKIN, NVL(SUM(KONKAITAXNUKIURIKIN), 0) + NVL(SUM(KONKAISHOHITAXKIN), 0) TAXKOMIURIKEIKIN, NVL(SUM(N8PERZEINUKIURIKIN), 0) + NVL(SUM(N8PERSHOHITAXKIN), 0) N8PERZEIKOMIRIYOGAKU, NVL(SUM(N10PERZEINUKIURIKIN), 0) + NVL(SUM(N10PERSHOHITAXKIN), 0) N10PERZEIKOMIRIYOGAKU, NVL(SUM(KURIKOSHIKIN), 0) KURIKOSHIKIN FROM ( SELECT SZDT.SKYSAKICD SKYSAKICD, SKSM.SKYKBN SKYKBN, SKSM.SKYSAKINMN1 SKYSAKINMN1, SZDT.ZNKKURIKOSHIKIN ZNKKURIKOSHIKIN, SZDT.KONKAINYKNKIN KONKAINYKNKIN, SZDT.KONKAITAXNUKIURIKIN KONKAITAXNUKIURIKIN, SZDT.KONKAISHOHITAXKIN KONKAISHOHITAXKIN, SZDT.N8PERZEINUKIURIKIN N8PERZEINUKIURIKIN, SZDT.N8PERSHOHITAXKIN N8PERSHOHITAXKIN, SZDT.N10PERZEINUKIURIKIN N10PERZEINUKIURIKIN, SZDT.N10PERSHOHITAXKIN N10PERSHOHITAXKIN, SZDT.KURIKOSHIKIN KURIKOSHIKIN FROM S07T001T SZDT LEFT OUTER JOIN S02M017T SKSM ON SZDT.APKIHONCD = SKSM.APKIHONCD AND SZDT.SHOPCD = SKSM.SHOPCD AND SZDT.SKYSAKICD = SKSM.SKYSAKICD WHERE SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND SZDT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND SZDT.SHIMEDD = #{shimedd,jdbcType=VARCHAR} AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND SZDT.KAISHUHOHOKBN = #{kaishuhohokbn,jdbcType=VARCHAR}
AND SZDT.RENBAN = #{renban,jdbcType=VARCHAR}
AND SZDT.YUKOKBN = '1' ) GROUP BY SKYSAKICD, SKYSAKINMN1, SKYKBN

SELECT TOKUISAKICD TOKUISAKICD, TOKUISAKINMN1 TOKUISAKINMN1, JIGYOSHOCD JIGYOSHOCD, JIGYOSHONM JIGYOSHONM, TOKUISAKIJOTAINM TOKUISAKIJOTAINM, JOTAISTSNM JOTAISTSNM, YUKOKBN YUKOKBN, SKYSAKICD SKYSAKICD, NVL(SUM(ZNKKURIKOSHIKIN), 0) ZNKKURIKOSHIKIN, NVL(SUM(KONKAINYKNKIN), 0) KONKAINYKNKIN, NVL(SUM(KONKAITAXNUKIURIKIN), 0) KONKAITAXNUKIURIKIN, NVL(SUM(KONKAISHOHITAXKIN), 0) KONKAISHOHITAXKIN, NVL(SUM(KONKAITAXNUKIURIKIN), 0) + NVL(SUM(KONKAISHOHITAXKIN), 0) TAXKOMISKYZDKIN, NVL(SUM(N8PERZEINUKIURIKIN), 0) + NVL(SUM(N8PERSHOHITAXKIN), 0) N8PERZEIKOMIRIYOGAKU, NVL(SUM(N10PERZEINUKIURIKIN), 0) + NVL(SUM(N10PERSHOHITAXKIN), 0) N10PERZEIKOMIRIYOGAKU, NVL(SUM(KURIKOSHIKIN), 0) KURIKOSHIKIN FROM ( SELECT SZDT.TOKUISAKICD TOKUISAKICD, TKSM.TOKUISAKINMN1 TOKUISAKINMN1, TKSM.JIGYOSHOCD JIGYOSHOCD, JGSM.JIGYOSHONM JIGYOSHONM, SKM_TOKUISAKIJOTAI.MOJISETTEIATAI TOKUISAKIJOTAINM, SKM_JOTAISTS.MOJISETTEIATAI JOTAISTSNM, TKSM.YUKOKBN YUKOKBN, SZDT.SKYSAKICD SKYSAKICD, SZDT.ZNKKURIKOSHIKIN ZNKKURIKOSHIKIN, SZDT.KONKAINYKNKIN KONKAINYKNKIN, SZDT.KONKAITAXNUKIURIKIN KONKAITAXNUKIURIKIN, SZDT.KONKAISHOHITAXKIN KONKAISHOHITAXKIN, SZDT.N8PERZEINUKIURIKIN N8PERZEINUKIURIKIN, SZDT.N8PERSHOHITAXKIN N8PERSHOHITAXKIN, SZDT.N10PERZEINUKIURIKIN N10PERZEINUKIURIKIN, SZDT.N10PERSHOHITAXKIN N10PERSHOHITAXKIN, SZDT.KURIKOSHIKIN KURIKOSHIKIN FROM S07T001T SZDT LEFT OUTER JOIN S02M013T TKSM ON SZDT.APKIHONCD = TKSM.APKIHONCD AND SZDT.SHOPCD = TKSM.SHOPCD AND SZDT.TOKUISAKICD = TKSM.TOKUISAKICD LEFT OUTER JOIN S02M047T JGSM ON TKSM.APKIHONCD = JGSM.APKIHONCD AND TKSM.SHOPCD = JGSM.SHOPCD AND TKSM.JIGYOSHOCD = JGSM.JIGYOSHOCD LEFT OUTER JOIN S02M006T SKM_TOKUISAKIJOTAI ON TKSM.TOKUISAKIJOTAI = SKM_TOKUISAKIJOTAI.SETTEICD AND '000' = SKM_TOKUISAKIJOTAI.APKIHONCD AND '000' = SKM_TOKUISAKIJOTAI.SHOPCD AND '014' = SKM_TOKUISAKIJOTAI.SETTEINO AND 'M' = SKM_TOKUISAKIJOTAI.RCRDKBN LEFT OUTER JOIN S02M006T SKM_JOTAISTS ON TKSM.JOTAISTS = SKM_JOTAISTS.SETTEICD AND '000' = SKM_JOTAISTS.APKIHONCD AND '000' = SKM_JOTAISTS.SHOPCD AND '015' = SKM_JOTAISTS.SETTEINO AND 'M' = SKM_JOTAISTS.RCRDKBN WHERE SZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} AND SZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR} AND SZDT.SHIMEDYDM = #{shimedydm,jdbcType=VARCHAR} AND SZDT.SHIMEDD = #{shimedd,jdbcType=VARCHAR} AND SZDT.SKYSAKICD = #{skysakicd,jdbcType=VARCHAR} AND SZDT.KAISHUHOHOKBN = #{kaishuhohokbn,jdbcType=VARCHAR}
AND SZDT.RENBAN = #{renban,jdbcType=VARCHAR}
AND SZDT.YUKOKBN = '1' ) GROUP BY TOKUISAKICD, SKYSAKICD, JIGYOSHOCD, JIGYOSHONM, TOKUISAKINMN1, TOKUISAKIJOTAINM, JOTAISTSNM, YUKOKBN ORDER BY TOKUISAKICD, SKYSAKICD

