UPDATE S07T001T
SET
    KSISHIMEDYDMDD = #{ksishimedydmdd,jdbcType=VARCHAR}
   ,KOSHAAPKIHONCD = #{koshaapkihoncd,jdbcType=VARCHAR}
   ,KOSHASHOPCD = #{koshashopcd,jdbcType=VARCHAR}
   ,KOSHACD = #{koshacd,jdbcType=VARCHAR}
   ,KSHNSYSTMYMD = #{kshnsystmymd,jdbcType=VARCHAR}
   ,KSHNSYSTMJIKAN = #{kshnsystmjikan,jdbcType=VARCHAR}
   ,KSHNUNYOYMD = #{kshnunyoymd,jdbcType=VARCHAR}
   ,KSHNIPADRSE = #{kshnipadrse,jdbcType=VARCHAR}
   ,KSHNPGMID = #{kshnpgmid,jdbcType=VARCHAR}
WHERE
    ROWID IN ( 
        SELECT
            ROWID 
        FROM
            ( 
                SELECT
                    SZDT.ROWID
                   ,TO_DATE(SZDT.SHIMEDYDM, 'yyyymm') SHIMEDYDM
                   ,SZDT.SHRYTIDYDMDD
                   ,CASE 
                        WHEN SHRSAITO = '2' 
                            THEN 1 
                        WHEN SHRSAITO = '3' 
                            THEN 2 
                        WHEN SHRSAITO = '4' 
                            THEN 3 
                        ELSE 0 
                        END YMDCOUNT
                   ,SKSM.SHRDD SHRDD
                   ,SZDT.KSISHIMEDYDMDD 
                FROM
                    S02M017T SKSM
                   ,S07T001T SZDT 
                WHERE
                    SKSM.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR} 
                AND SKSM.SHOPCD = #{shopcd,jdbcType=VARCHAR}
                AND SKSM.KSIKKNCD = #{ksikkncd,jdbcType=VARCHAR} 
                AND SKSM.APKIHONCD = SZDT.APKIHONCD 
                AND SKSM.SHOPCD = SZDT.SHOPCD 
                AND SKSM.SKYSAKICD = SZDT.SKYSAKICD 
                AND ( 
                       SZDT.KSISHIMEDYDMDD = '00000000' 
                    OR SZDT.KSISHIMEDYDMDD = #{shimedydm,jdbcType=VARCHAR} || #{shimedd,jdbcType=VARCHAR}
                    ) 
                AND ( 
                       SZDT.KAISHUHOHOKBN = '5' 
                    OR SZDT.KAISHUHOHOKBN = '2'
                    )
                AND SZDT.YUKOKBN = '1'
            ) 
        WHERE
            SHRYTIDYDMDD = #{shrytidydmdd,jdbcType=VARCHAR}
    )
